console.log('clicked Top up');
await page.waitForURL(/checkout\.stripe\.com/);
console.log('reached ' + page.url().slice(0, 48) + '…');
const captcha = await page.locator('iframe[src*="hcaptcha"]').count();
if (captcha) console.log('hCaptcha challenge iframe present; "Pay" stays disabled');
await browser.close();

